import {timelineMinimumSpan} from './timeline-view.js';
// Background gestures leave key/clip drags to their existing authoring handler.
export function installTimelineTouchNavigation(element,hooks){
 if(!hooks.data)return ()=>{};const points=new Map(),window=element.ownerDocument.defaultView;let gesture=null;
 const band=()=>element.querySelector('.gameplay-ruler>div')?.getBoundingClientRect()||element.getBoundingClientRect();
 const sample=()=>{const [a,b]=[...points.values()];return b?{x:(a.x+b.x)/2,y:(a.y+b.y)/2,distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))}:{...a,distance:1};};
 const rebase=()=>{gesture.base=hooks.range();gesture.point=sample();gesture.top=element.scrollTop;};
 const cancel=()=>{if(!gesture)return;const before=gesture;gesture=null;const ids=[...points.keys()];points.clear();for(const id of ids)if(element.hasPointerCapture(id))element.releasePointerCapture(id);hooks.set(before.original);element.scrollTop=before.originalTop;window.removeEventListener('blur',cancel);window.removeEventListener('keydown',escape,true);};
 const escape=event=>{if(event.key==='Escape'&&gesture){event.preventDefault();event.stopImmediatePropagation();cancel();}};
 const down=event=>{if(event.pointerType!=='touch'||hooks.busy?.()||!gesture&&(event.target.closest('[data-select-item],[data-select-track]')||!event.target.closest('.gameplay-ruler>div,.gameplay-track-band')))return;event.preventDefault();event.stopImmediatePropagation();if(points.size>=2)return;points.set(event.pointerId,{x:event.clientX,y:event.clientY});if(!gesture){element.focus({preventScroll:true});hooks.begin?.();gesture={original:hooks.range(),originalTop:element.scrollTop,moved:false,pinched:false};window.addEventListener('blur',cancel);window.addEventListener('keydown',escape,true);}if(points.size===2)gesture.pinched=true;rebase();element.setPointerCapture(event.pointerId);};
 const move=event=>{if(!gesture||!points.has(event.pointerId))return;event.preventDefault();event.stopImmediatePropagation();points.set(event.pointerId,{x:event.clientX,y:event.clientY});const now=sample(),before=gesture.point,dx=now.x-before.x,dy=now.y-before.y;if(!gesture.moved&&Math.hypot(dx,dy)<3&&Math.abs(now.distance-before.distance)<3)return;if(!gesture.moved)hooks.begin?.();gesture.moved=true;const rect=band(),width=Math.max(1,rect.width),range=gesture.base,span=range.end-range.start;
  if(points.size===2){const nextSpan=Math.max(timelineMinimumSpan(hooks.data()),Math.min(hooks.data().length,span*before.distance/now.distance)),anchor=range.start+(before.x-rect.left)/width*span,start=anchor-(now.x-rect.left)/width*nextSpan;hooks.set({start,end:start+nextSpan});}
  else{const start=range.start-dx/width*span;hooks.set({start,end:start+span});element.scrollTop=Math.max(0,gesture.top-dy);}
 };
 const up=event=>{if(!gesture||!points.has(event.pointerId))return;event.preventDefault();event.stopImmediatePropagation();if(event.type!=='pointerup'){cancel();return;}const last=gesture;points.delete(event.pointerId);if(element.hasPointerCapture(event.pointerId))element.releasePointerCapture(event.pointerId);if(points.size){rebase();return;}gesture=null;window.removeEventListener('blur',cancel);window.removeEventListener('keydown',escape,true);if(!last.moved&&!last.pinched){const rect=band(),range=hooks.range();hooks.scrub?.(range.start+(event.clientX-rect.left)/Math.max(1,rect.width)*(range.end-range.start));}};
 element.addEventListener('pointerdown',down,true);element.addEventListener('pointermove',move,true);element.addEventListener('pointerup',up,true);element.addEventListener('pointercancel',up,true);element.addEventListener('lostpointercapture',up,true);
 return ()=>{cancel();element.removeEventListener('pointerdown',down,true);element.removeEventListener('pointermove',move,true);element.removeEventListener('pointerup',up,true);element.removeEventListener('pointercancel',up,true);element.removeEventListener('lostpointercapture',up,true);};
}
